import { useCallback, useEffect, useState } from 'react';
import { useMediaQuery } from 'usehooks-ts';
import type { colorModeClasses } from '@rbx/foundation-tailwind/classes';

const colorModes: typeof colorModeClasses = [
  'color-mode-dark',
  'color-mode-light',
  'color-mode-system'
] as const;

/**
 * The effective color mode (either `light` or `dark`).
 *
 * If the active color mode is `system`, then a `prefers-color-scheme` media query is used to resolve it to either `light` or `dark`.
 */
export type ResolvedColorMode = 'light' | 'dark';

/**
 * Returns the currently resolved, global color mode based on the `document.body` and `document.documentElement`.
 *
 * This hook does not account for color mode overrides in other parts of the DOM.
 *
 * The initial value is `light` so server and client rendering produce the same output.
 * The effective client color mode is resolved after mounting.
 *
 * If the active color mode is `system`, then a `prefers-color-scheme` media query is used to resolve it to either `light` or `dark`.
 */
export default function useResolvedColorMode(): ResolvedColorMode {
  const prefersDark = useMediaQuery('(prefers-color-scheme: dark)', {
    defaultValue: false,
    initializeWithValue: false
  });

  const detectLightDark = useCallback((): ResolvedColorMode => {
    if (typeof document !== 'undefined') {
      const element = [document.body, document.documentElement].find(e =>
        colorModes.some(c => e.classList.contains(c))
      );

      if (element?.classList.contains('color-mode-dark')) return 'dark';
      if (element?.classList.contains('color-mode-light')) return 'light';
    }

    return prefersDark ? 'dark' : 'light';
  }, [prefersDark]);

  const [lightDark, setLightDark] = useState<ResolvedColorMode>('light');

  useEffect(() => {
    setLightDark(detectLightDark());

    if (typeof document === 'undefined' || typeof MutationObserver === 'undefined') {
      return undefined;
    }

    const observer = new MutationObserver(() => {
      setLightDark(detectLightDark());
    });
    const options: MutationObserverInit = { attributes: true, attributeFilter: ['class'] };

    observer.observe(document.documentElement, options);
    observer.observe(document.body, options);

    return () => {
      observer.disconnect();
    };
  }, [detectLightDark]);

  return lightDark;
}
